    "outsideTropical": "{plant}은(는) 따뜻한 열대 기후에서 잘 자라고 존 9 미만에선 힘들어해요. 추운 곳에선 겨울에 실내로 옮길 수 있는 큰 화분에 키우세요.",
    "outsideTree": "{plant}은(는) 현재 존 밖에서 더 잘 자라요. 지역에 맞는 내한성 품종을 가까운 묘목상에 문의해 보세요.",
    "outsideOther": "{plant}은(는) 보통 현재 존 밖에서 재배돼요. 미기후에 따라 화분, 높은 화단, 온실로 성공할 수도 있어요.",
    "frost": "{plant}은(는) 이 존에 잘 맞지만 서리 예보가 있어요. 밤 최저 기온이 꾸준히 40°F를 넘을 때까지 아주심기는 미루세요. 지금은 실내 파종이 좋아요.",
    "heatCool": "{plant}은(는) 서늘한 기온을 좋아해 지금 더위에선 힘들어해요. 80°F 아래로 내려갈 때까지 기다리거나 아침 햇빛만 드는 그늘에 심으세요.",
    "heatLover": "{plant}은(는) 더위를 좋아하고 이 존에서 잘 자라요. 이른 아침에 심고, 깊게 물 주고, 멀칭을 두껍게 해 오후 더위로부터 뿌리를 보호하세요.",
    "heatOther": "{plant}은(는) 더위를 견디지만 지금은 기온이 높아요. 아침에 깊게 물 주고, 멀칭하고, 가장 더운 시간엔 옮겨 심지 마세요.",
    "easy": "{plant}은(는) 초보자에게 좋고 이 존에 훌륭한 선택이에요. 너그럽고 빨리 자라며 꾸준한 물주기와 좋은 흙에 확실한 수확으로 보답해요. 누구에게나 좋은 시작이에요.",
    "hard": "{plant}은(는) 손이 더 가지만 {zone}에서 키울 가치가 충분해요. 흙 준비, 꾸준한 물주기, 해충 관찰에 집중하세요. 노력은 멋진 수확으로 돌아와요.",
    "medium": "{plant}은(는) 제철에 심으면 {zone}에서 무난한 선택이에요. 퇴비로 흙을 준비하고 꾸준히 물 주며 통풍과 건강한 생장을 위해 간격을 충분히 두세요.",
