    "marigold_zinnia": "요구 조건이 같은 화사하고 키우기 쉬운 한해살이꽃으로, 메리골드가 화단의 병해충 저항력을 높여 줘요.",
    "marigold_nasturtium": "든든한 동반 식물 두 가지로, 함께 심으면 진딧물을 유인하고 해충을 막아 줘요.",
    "pansy_viola": "서늘한 계절을 좋아하는 사촌 같은 꽃으로, 같은 환경에서 잘 자라 봄과 가을을 물들여 줘요.",
    "astilbe_bleeding_heart": "숲속 그늘을 좋아하는 식물들로, 서늘하고 촉촉한 흙을 똑같이 좋아해요.",
    "grape_hyacinth_tulip": "무스카리는 튤립 아래에 깔아 주는 전통적인 카펫으로, 봄 화단을 층층이 화려하게 만들어 줘요.",
    "lily_phlox": "여름 화단의 단짝으로, 플록스가 백합 줄기 주변을 채워 주며 햇빛과 물 조건도 똑같아요.",
    "bee_balm_phlox": "둘 다 흰가루병에 매우 취약해서 바람이 잘 안 통하는 곳에 함께 심으면 빠르게 번져요. 각각 공간과 통풍을 넉넉히 주세요.",
    "morning_glory_rose": "나팔꽃은 왕성하게 자라고 스스로 씨를 퍼뜨리는 덩굴 식물로, 장미 줄기를 타고 올라 뒤덮으며 물을 두고 경쟁해요.",
    "basil_pepper": "바질이 피망의 향을 가려 진딧물과 총채벌레의 눈을 피하게 도와줘요.",
    "carrot_lettuce": "상추가 흙에 그늘을 드리워 당근 뿌리를 시원하고 촉촉하게 유지해 줘요.",
