    "bean_corn": "콩은 옥수수 줄기를 타고 올라가며 흙에 질소를 보충해 줘요. '세 자매' 농법의 절반이죠.",
    "corn_cucumber": "옥수수는 오이 덩굴이 타고 오를 지지대가 되어 주고 가벼운 그늘도 만들어 줘요.",
    "lettuce_radish": "래디시는 흙을 부드럽게 해 주고, 상추가 자리를 필요로 하기 전에 수확할 수 있어요.",
    "marigold_pepper": "메리골드는 진딧물을 피망에서 멀리 끌어내고 이로운 곤충을 불러 모아요.",
    "beet_lettuce": "비트는 아래로, 상추는 옆으로 자라서 화단의 서로 다른 층을 써요.",
