    "basil_peach": "바질은 진딧물을 쫓아내고 복숭아나무 잎을 해충으로부터 지켜 줘요.",
    "bean_celery": "콩은 흙에 질소를 공급하고, 셀러리는 콩의 뿌리에 그늘을 만들어 줘요.",
    "bean_pea": "둘 다 스스로 질소를 고정하기 때문에 서로 다투지 않고 한 화단에서 함께 자랄 수 있어요.",
