    "black_eyed_susan_coneflower": "프레리를 대표하는 짝꿍이에요. 햇볕을 좋아하는 튼튼한 자생 식물로, 몇 주 동안 꽃을 피우며 수분 매개 곤충에게 먹이를 줘요.",
