    "cosmos_sunflower": "하늘하늘한 코스모스가 키 큰 해바라기를 부드럽게 감싸 주고, 둘 다 햇볕을 좋아하고 수분 매개 곤충에게 인기 있는 한해살이 식물이에요.",
    "snapdragon_sweet_alyssum": "곧게 선 금어초 아래로 거품처럼 퍼지는 스위트 알리섬이 치마처럼 깔리는, 요구 조건까지 똑같은 화단의 정석이에요.",
    "astilbe_hosta": "그늘 정원의 정석이에요. 둘 다 촉촉하고 그늘진 흙을 좋아하고, 큼직한 잎과 깃털 같은 꽃이삭이 잘 어울려요.",
    "begonia_impatiens": "그늘 화단에서 믿음직한 짝꿍으로, 빛과 물에 대한 요구가 똑같아요.",
