    "cosmos_dahlia": "늦여름 절화 정원의 짝꿍으로, 서리가 내릴 때까지 꽃을 피워요.",
    "hollyhock_lavatera": "둘 다 아욱과라서 접시꽃 녹병을 함께 앓아요. 곰팡이가 옮겨 가지 않게 떨어뜨려 심어 주세요.",
    "basil_oregano": "둘 다 향긋한 허브로 물과 햇빛 요구량이 같아 함께 키우기 쉬운 이웃이에요.",
    "carrot_tomato": "토마토는 오후에 당근에게 그늘을 만들어 주고, 당근은 뿌리 주변 흙을 부드럽게 해 줘요.",
    "corn_squash": "호박 잎이 땅에 그늘을 드리우고 잡초를 막아 주며 옥수수를 위해 흙의 수분을 지켜 줘요.",
