    "basil_1": "마지막 서리 6주 전에 실내에서 씨앗을 틔우거나, 서리가 지난 뒤 직접 파종하세요.",
    "basil_5": "꽃봉오리가 보이면 바로 따 주어야 잎의 향이 유지됩니다.",
