    "mint_6": "줄기를 자주 수확하세요. 딸수록 더 풍성하게 자랍니다.",
    "rosemary_3": "물은 깊이, 하지만 드문드문 주세요. 로즈마리는 자리를 잡으면 가뭄에 강합니다.",
    "rosemary_7": "추운 지역에서는 화분에 키우고 겨울에는 실내로 들여놓으세요.",
