    "cilantro_1": "서늘한 날씨에 씨앗을 직접 뿌리세요. 고수는 더우면 금세 꽃대가 올라옵니다.",
    "cilantro_5": "식물 키가 {m1}가 되면 바깥쪽 잎부터 수확하세요.",
    "parsley_2": "기름지고 촉촉한 흙에 {m1} 깊이로 뿌리세요. 양지에서 반그늘까지 괜찮습니다.",
    "parsley_6": "바깥쪽 줄기부터 수확하고, 줄기 밑동에서 잘라 주세요.",
    "fennel_3": "씨앗은 {m1} 깊이로, {m2} 간격으로 뿌리세요.",
    "fennel_7": "일부 식물은 씨앗이 맺히도록 두었다가 늦여름에 펜넬 씨앗을 수확하세요.",
    "strawberry_4": "짚으로 멀칭하면 열매가 깨끗하게 유지되고 흙도 촉촉하게 유지됩니다.",
    "blueberry_1": "햇볕이 잘 들고 산성도가 매우 높은 흙(pH 4.5~5.5)인 자리를 고르세요.",
    "blueberry_5": "흙의 산성을 유지하려면 우드칩이나 소나무 껍질로 두툼하게 멀칭하세요.",
    "raspberry_2": "줄기는 {m1} 간격으로, 줄 간격은 {m2}로 심으세요.",
    "raspberry_6": "두툼하게 멀칭해 잡초를 억제하고 수분을 지키세요.",
    "apple_3": "뿌리 분의 두 배 너비에 같은 깊이로 구덩이를 파세요.",
    "apple_7": "매년 늦겨울에 가지치기를 해서 수관을 트이게 하고 통풍을 좋게 유지하세요.",
    "peach_4": "첫 생육 시즌에는 매주 깊이 물을 주세요.",
    "lemon_1": "정원에서 가장 따뜻하고 햇볕이 잘 드는 자리나 큰 화분에 심으세요.",
    "lemon_5": "생육기에는 6~8주마다 감귤류 전용 비료를 주세요.",
    "avocado_2": "배수가 빠른 흙을 쓰세요. 아보카도는 뿌리 썩음에 매우 민감합니다.",
