    "pomegranate_4": "자리를 잡은 뒤에는 물을 깊이, 하지만 드문드문 주세요.",
    "typeHerbs_1": "배수가 아주 좋고 햇볕이 잘 드는 화분, 높은 화단, 또는 정원 자리를 고르세요.",
