    "typeTreeFruits_3": "접붙인 부위가 흙 위로 올라오게 하세요.",
    "typeBerries_1": "햇볕이 잘 들고 기름지며 배수가 좋은 약산성 흙인 자리를 고르세요.",
    "typeBerries_5": "봄에 칼륨이 풍부한 비료를 주세요.",
    "tomato_3": "통풍을 좋게 하고 병을 예방하려면 식물 간격을 {m1}로 띄워 주세요.",
