    "cucumber_5": "흠뻑, 꾸준히 물을 주세요. 오이는 95%가 수분이라 일정한 습도가 필요합니다.",
    "zucchini_2": "씨앗을 2–3개씩 모아 심고, 가장 튼튼한 한 포기만 남기고 솎아 주세요.",
    "zucchini_6": "최상의 맛과 식감을 위해 주키니는 길이가 {m1}일 때 수확하세요.",
    "carrot_3": "씨앗을 {m1} 간격의 줄에 듬성듬성 뿌리고 흙은 {m2}만 덮어 주세요.",
    "carrot_7": "잎이 완전히 색이 들면 수확하세요. 뽑기 전에 포크로 흙을 살살 풀어 주세요.",
    "lettuce_4": "물을 적게 자주 주세요. 상추는 뿌리가 얕아서 금방 마릅니다.",
