    "spinach_5": "잎이 무성하게 자라도록 질소가 풍부한 비료를 주세요.",
    "kale_2": "햇볕이 잘 드는 곳이나 반그늘의 비옥하고 배수가 잘되는 흙에 심으세요.",
    "kale_6": "바깥쪽 잎부터 수확하고 가운데는 계속 자라도록 남겨 두세요.",
    "broccoli_3": "식물 간격은 {m1}, 줄 너비는 {m2}로 하세요.",
    "broccoli_7": "중심 송이를 자른 뒤에도 몇 주 동안 곁순을 계속 수확하세요.",
    "cabbage_4": "규칙적으로 물을 주세요. 양배추는 90%가 수분이라 일정한 습도가 필요합니다.",
