    "garlic_7": "아래쪽 잎은 갈색으로 변하고 위쪽 잎은 아직 초록일 때 수확하세요. 보통 6월이나 7월입니다.",
    "corn_4": "일주일에 한 번 흠뻑 물을 주세요. 옥수수는 매주 {m1}의 물이 필요합니다.",
