    "bean_5": "잎에 곰팡이병이 생기지 않도록 위에서 물을 뿌리지 마세요.",
    "pea_2": "씨앗은 깊이 {m1}, 간격 {m2}로, 줄 간격 {m3}으로 심으세요.",
    "pea_6": "꼬투리가 통통하고 선명한 초록색일 때 수확하세요. 하나 맛보고 단맛을 확인해 보세요.",
    "radish_3": "싹이 나면 간격이 {m1}가 되도록 솎아 주세요.",
    "radish_7": "서늘한 계절 내내 계속 수확하려면 2주마다 나누어 파종하세요.",
    "beet_4": "모종 간격이 {m1}가 되도록 솎아 주세요. 비트 씨앗 하나는 사실 여러 씨앗이 뭉친 것입니다.",
    "eggplant_1": "마지막 서리 8–10주 전에 실내에서 씨앗을 틔우세요. 가지는 따뜻한 시기가 길어야 합니다.",
    "eggplant_5": "흙을 따뜻하게 유지하고 수분을 지키려면 두툼하게 멀칭하세요.",
