    "pumpkin_7": "껍질이 단단하고 색이 완전히 들었으며 꼭지가 마르기 시작하면 수확하세요.",
    "watermelon_4": "덩굴이 뻗기 전까지는 질소 비료를 주고, 이후에는 인 비료로 바꾸세요.",
