    "basil_6": "잎마디 바로 위에서 줄기를 따 주면 풍성하게 자랍니다.",
    "mint_3": "촉촉하고 비옥한 흙에 심고 규칙적으로 물을 주세요.",
    "mint_7": "일년 내내 신선한 민트를 즐기려면 서리가 내리기 전에 화분을 실내로 들여놓으세요.",
    "rosemary_4": "비료를 과하게 주지 마세요. 메마른 흙이 오히려 풍미를 높여 줍니다.",
    "thyme_1": "햇볕이 잘 들고 배수가 아주 잘되는 흙에 심으세요. 타임은 가뭄에 강합니다.",
    "thyme_5": "향이 가장 진하도록 꽃이 피기 전에 줄기를 수확하세요.",
    "cilantro_2": "깊이 {m1}로, 줄 간격 {m2}로 심으세요.",
    "cilantro_6": "몇 포기는 꽃대가 올라와 씨앗을 맺도록 두세요. 고수 씨앗도 먹을 수 있습니다.",
    "parsley_3": "모종 간격이 {m1}가 되도록 솎아 주세요. 파슬리는 자랄 공간이 필요합니다.",
    "parsley_7": "파슬리는 2년생 식물이라 겨울을 나고 두 번째 해에 꽃이 핍니다.",
    "fennel_4": "자리 잡을 때까지 규칙적으로 물을 주세요. 다 자란 펜넬은 가뭄에 강합니다.",
    "strawberry_1": "이른 봄에 햇볕이 잘 들고 배수가 잘되는 약산성 흙에 심으세요.",
